#include <stdio.h>
#include <string.h>
#include <stdbool.h>

#define MAXLEN 64   /* maximum length accepted for pattern and text */

/* Returns true if pattern matches text using '?' and '*' wildcards. */
static bool wildcard_match(const char *pattern, const char *text)
{
    size_t p_len = strlen(pattern);
    size_t t_len = strlen(text);

    /* dp[i][j] – pattern[0..i-1] matches text[0..j-1] */
    bool dp[MAXLEN + 1][MAXLEN + 1] = { false };

    dp[0][0] = true;                     /* empty pattern matches empty text */

    /* Initialise first column: pattern vs empty text.
       Only a leading sequence of '*' can match an empty string. */
    for (size_t i = 1; i <= p_len; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];
        else
            dp[i][0] = false;
    }

    /* Fill the DP table. */
    for (size_t i = 1; i <= p_len; ++i) {
        for (size_t j = 1; j <= t_len; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];

            if (pc == '*') {
                /* '*' matches empty (dp[i-1][j]) or consumes one character (dp[i][j-1]) */
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            } else if (pc == '?' || pc == tc) {
                dp[i][j] = dp[i - 1][j - 1];
            } else {
                dp[i][j] = false;
            }
        }
    }

    return dp[p_len][t_len];
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    if (strlen(pattern) >= MAXLEN || strlen(text) >= MAXLEN) {
        puts("USAGE");
        return 0;
    }

    if (wildcard_match(pattern, text))
        puts("MATCH");
    else
        puts("NO_MATCH");

    return 0;
}
